    66  zmq::zmtp_engine_t::zmtp_engine_t (
    67    fd_t fd_,
    68    const options_t &options_,
    69    const endpoint_uri_pair_t &endpoint_uri_pair_) :
    70      stream_engine_base_t (fd_, options_, endpoint_uri_pair_),
    71      _greeting_size (v2_greeting_size),
    72      _greeting_bytes_read (0),
    73      _subscription_required (false),
    74      _heartbeat_timeout (0)
    75  {
