   149  int zmq::zmtp_engine_t::receive_greeting ()
   150  {
   151      bool unversioned = false;
   152      while (_greeting_bytes_read < _greeting_size) {
   153          const int n = read (_greeting_recv + _greeting_bytes_read,
   154                              _greeting_size - _greeting_bytes_read);
   155          if (n == -1) {
   156              if (errno != EAGAIN)
   157                  error (connection_error);
   158              return -1;
   159          }
   160
   161          _greeting_bytes_read += n;
   162
   163          //  We have received at least one byte from the peer.
   164          //  If the first byte is not 0xff, we know that the
   165          //  peer is using unversioned protocol.
   166          if (_greeting_recv[0] != 0xff) {
   167              unversioned = true;
   168              break;
   169          }
   170
   171          if (_greeting_bytes_read < signature_size)
   172              continue;
   173
   174          //  Inspect the right-most bit of the 10th byte (which coincides
   175          //  with the 'flags' field if a regular message was sent).
   176          //  Zero indicates this is a header of a routing id message
   177          //  (i.e. the peer is using the unversioned protocol).
   178          if (!(_greeting_recv[9] & 0x01)) {
   179              unversioned = true;
   180              break;
   181          }
   182
   183          //  The peer is using versioned protocol.
   184          receive_greeting_versioned ();
   185      }
   186      return unversioned ? 1 : 0;
   187  }
