   189  void zmq::zmtp_engine_t::receive_greeting_versioned ()
   190  {
   191      //  Send the major version number.
   192      if (_outpos + _outsize == _greeting_send + signature_size) {
   193          if (_outsize == 0)
   194              set_pollout ();
   195          _outpos[_outsize++] = 3; //  Major version number
   196      }
   197
   198      if (_greeting_bytes_read > signature_size) {
   199          if (_outpos + _outsize == _greeting_send + signature_size + 1) {
   200              if (_outsize == 0)
   201                  set_pollout ();
   202
   203              //  Use ZMTP/2.0 to talk to older peers.
