   501  int zmq::zmtp_engine_t::produce_pong_message (msg_t *msg_)
   502  {
   503      zmq_assert (_mechanism != NULL);
   504
   505      int rc = msg_->move (_pong_msg);
   506      errno_assert (rc == 0);
   507
   508      rc = _mechanism->encode (msg_);
   509      _next_msg = &zmtp_engine_t::pull_and_encode;
   510      return rc;
   511  }
