   513  int zmq::zmtp_engine_t::process_heartbeat_message (msg_t *msg_)
   514  {
   515      if (msg_->is_ping ()) {
   516          // 16-bit TTL + \4PING == 7
   517          const size_t ping_ttl_len = msg_t::ping_cmd_name_size + 2;
   518          const size_t ping_max_ctx_len = 16;
   519          uint16_t remote_heartbeat_ttl;
   520
   521          // Get the remote heartbeat TTL to setup the timer
   522          memcpy (&remote_heartbeat_ttl,
   523                  static_cast<uint8_t *> (msg_->data ())
   524                    + msg_t::ping_cmd_name_size,
   525                  ping_ttl_len - msg_t::ping_cmd_name_size);
   526          remote_heartbeat_ttl = ntohs (remote_heartbeat_ttl);
   527          // The remote heartbeat is in 10ths of a second
   528          // so we multiply it by 100 to get the timer interval in ms.
   529          remote_heartbeat_ttl *= 100;
   530
   531          if (!_has_ttl_timer && remote_heartbeat_ttl > 0) {
   532              add_timer (remote_heartbeat_ttl, heartbeat_ttl_timer_id);
   533              _has_ttl_timer = true;
   534          }
   535
   536          //  As per ZMTP 3.1 the PING command might contain an up to 16 bytes
   537          //  context which needs to be PONGed back, so build the pong message
   538          //  here and store it. Truncate it if it's too long.
   539          //  Given the engine goes straight to out_event, sequential PINGs will
   540          //  not be a problem.
   541          const size_t context_len =
   542            std::min (msg_->size () - ping_ttl_len, ping_max_ctx_len);
   543          const int rc =
   544            _pong_msg.init_size (msg_t::ping_cmd_name_size + context_len);
   545          errno_assert (rc == 0);
   546          _pong_msg.set_flags (msg_t::command);
   547          memcpy (_pong_msg.data (), "\4PONG", msg_t::ping_cmd_name_size);
   548          if (context_len > 0)
   549              memcpy (static_cast<uint8_t *> (_pong_msg.data ())
   550                        + msg_t::ping_cmd_name_size,
   551                      static_cast<uint8_t *> (msg_->data ()) + ping_ttl_len,
   552                      context_len);
   553
   554          _next_msg = static_cast<int (stream_engine_base_t::*) (msg_t *)> (
   555            &zmtp_engine_t::produce_pong_message);
   556          out_event ();
   557      }
   558
   559      return 0;
   560  }
